import jsonfrom docker_manager import generate_dockerfile, build_docker_image, run_docker_containerfrom db_initializer import exec_sql_scriptfrom sqlancer_runner import run_sqlancerdef load_config(path="default.json"):    with open(path, "r") as file:        return json.load(file)def main():    config = load_config()    generate_dockerfile()    build_docker_image(config["image_name"])    run_docker_container(config["image_name"], config["container_name"], config["port"])    exec_sql_script(config["container_name"], config["root_password"], config["sql_script_path"])    run_sqlancer(        root_password=config["root_password"],        threads=config["sqlancer_threads"],        timeout=config["sqlancer_timeout"],        jar_file=config["sqlancer_jar"]    )if __name__ == "__main__":    main()